import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"西溪易说卷八","description":"西溪易说 - 西溪易说卷八","frontmatter":{"title":"西溪易说卷八","description":"西溪易说 - 西溪易说卷八"},"headers":[],"relativePath":"zh/classics/xixi/009.md","filePath":"zh/classics/xixi/009.md"}'),i={name:"zh/classics/xixi/009.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易说卷八" tabindex="-1">西溪易说卷八 <a class="header-anchor" href="#西溪易说卷八" aria-label="Permalink to “西溪易说卷八”">​</a></h1><p>钦定四库全书</p><p>宋李过撰</p><p>䷣ 离下坤上 明夷，</p><p>明夷：利艰贞。彖曰：明入地中，明夷。内文明而外柔顺，以蒙大难，文王以之。「利艰贞」，晦其明也。内难而能正其志，箕子以之。明出地上，明世也；明入地中，暗世也。晋变而明夷，文王之心其在是乎？夫子曰：「作易者，其有忧患乎？」其当殷之末世，文王与纣之时乎？吾独于晋明夷见之。晋之君臣以礼相遇，交际之盛，夏、商盛时亦莫不然。有如文王之事商而不免于囚，箕子之事商而不免于狂，此非箕子、文王之所当得也，盖至此而后可以言命。重易而至明夷，离居坤下，明不当天而入于地中，其己之所遇欤？扬雄曰：「龙以不制为龙，圣人以不平为圣人。」以文王之纯德，陟降上帝，而羑里之难，固不足为文王累。以事君小心，天实临之，而不免于疑与囚，文王岂能释然于其心哉？故其重易也，于明夷略见一二，且婉其辞而托诸箕子。越五百岁，而夫子系易，始探其心于韦编三绝之后。于是乎作彖而明言其事，曰：内文明而外柔顺，以蒙大难，文王以之。利艰贞，晦其明也。内难而能正其志，箕子以之。又作象以系于爻辞之下，而于内卦之六二曰：「六二之吉，顺以则也。」盖文王至是而昭昭矣。夫子曰：「文王既没，文不在兹乎？」信乎其神交而精契也。就六爻观之，外卦则箕子用之，内卦则文王用之。卦辞「利艰贞」，文王为箕子发也。盖内难而能正其志，箕子之事也。爻既言之矣，使彖不言文王之事，孰知夫内明外顺以蒙大难之为文王事耶？然夫子既明言之，二千年来谈易者未有得其心者。噫！圣贤契合，固如是之难也哉！</p><p>象曰：明入地中，明夷，君子以莅众，用晦而明。日入于地，明夷之象也。晦其明以莅众，处明夷之世之道也。君子处乱世，惟其有平治天下之志，故遵养于其间而不为苟去，外虽用晦，而中盖甚明也。</p><p>初九，明夷于飞，垂其翼；君子于行，三日不食。有攸往，主人有言。象曰：「君子于行」，义不食也。</p><p>内卦，文王事。初爻言其被囚而去也。当「明夷」之时，飞而垂翼，缧其手也。「君子于行」，受絷而去也。「三日不食」，受患之至也。圣人处患难，何忧哉？亲之过大而不怨，是愈疏也。「主人有言」，君有疑言。象曰：义不食也。以君臣之义言之，故当不食也。</p><p>六二：明夷于左股，用拯马壮，吉。象曰：六二之「吉」，顺以则也。</p><p>二，言其在羑里也。伤及其股，谓其足梏而不得行也。「用拯马壮吉」，圣人已有知患难之理。方其在难也，人以为难，而圣人已拯壮马以出，知时之不能害己也。象曰：「顺以则也」。此看得夫子尽见文王之心。圣人举措纯乎天理。文王之出患难，自循夫理之外，不容一毫私意。诗曰：「帝谓文王，不大声以色，不长夏以革。不识不知，顺帝之则。」文王纯乎顺帝则也。其出羑里，用此道也。司马迁作史记，乃谓闳、散辈以计出文王。如此立言，其得罪于圣人也不可赎。</p><p>九三：明夷于南狩，得其大首，不可疾，贞。象曰：「南狩」之志，乃大得也。</p><p>三言其出羑里，受命为西伯也。文王之化行于南国，故出而南狩，伐崇庸，伐密人，得其大首也。然文王征伐止此而已，所谓「三分天下有其二，以服事殷」者，其事殷之心，直不可得而瑕疵也。故文王处明夷则以「不可疾贞」；箕子处明夷则以「利艰贞」。二者各当其事可也，故曰「不可疾贞」。象曰：「乃大得也」。江汉以南，皆被文王之化，可谓「大得志也」。然文王在囚，而重爻犹未出难也，安知其南狩之事哉？曰：圣人重易，千万世无穷之变可以逆定，况于其身而当世之事变耶！六四，入于左腹，获明夷之心，于出门庭。象曰：「入于左腹」，获心意也。</p><p>外卦箕子用之，此言其徉狂时也。「入于左腹」，狂左道也。入于纣腹，于是得纣之心意，乃出纣之门庭，而纣不加罪，故曰「于出门庭」。象曰：「获心意也」，言得纣之心意也。当是时，微子不免于行道，比干不免于焚炙，而箕子独以奴免，非「入于左腹」，安可得也！</p><p>六五，箕子之明夷，利贞。象曰：箕子之贞，明不可息也。五言箕子之能正其志也。卦辞「利艰贞」，全属箕子。艰者，难也；贞者，正也。言箕子处内难而其志则正也。故于此曰「箕子之明夷，利贞」，谓如箕子之处明夷，志正则宜也。象曰：「明不可息也」，言箕子之明处未尝息也。武王兴，缧囚释而洪范作，彝伦九畴绝而复续，非晦于昔而明于今也，天理本未尝息也。</p><p>上六：不明晦，初登于天，后入于地。象曰：「初登于天」，照四国也。「后入于地」，失则也。此言纣也。「不明晦」，言明入地中，不明而晦也。始亦正位，故「初登于天」；后失君道，故「后入于地」。象曰：「初登于天」，照四国也。后入于地，失则也。理之至当而不可过为则，君自有君之则。纣失君道，故曰失则。</p><p>看。明夷卦每谓文王之心，千载而上惟夫子知之，千载而下惟韩子知之。箕子之志，千载而上惟夫子知之，千载而下，惟柳子知之。韩文公羑里操曰：「目闪闪兮其凝其盲，耳萧萧兮听不声闻。朝不见日出兮，夜不见月与星。有知无知兮，为死为生。臣罪当诛兮，天王圣明。」可谓得文王之心。柳子厚作箕子庙碑有云：「当是时，周时未至，商祀未殄，微子已去，比干已死。向使纣恶未稔而先毙，武庚念乱以图存，国无其人，谁与共理？此则人事之或然者也。先生隐忍而就此，其亦有志于斯乎？」可谓见得箕子之心。䷤ 离下巽上 家人，</p><p>家人：利女贞。彖曰：家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父子子，兄兄弟弟，夫夫妇妇，而家道正，正家而天下定矣。家人，正家之道也。有男女而后有夫妇，有夫妇而后有父子，有父子而后有兄弟。夫妇、父子、兄弟，人之大伦也。古人自修身齐家推之于治国平天下，莫不以此卦。九居五，男在外也。六居二，女在内也。齐家之道，莫先于正女，女正则内治，内治则外治矣，故曰「利女贞」。据彖辞，六爻皆说尽，大抵男女各有其位而不相乱也。古人治家，莫先于辨男女之位，如「内言不出于阃，外言不入于阃」之类。卦分内外，男女之位也。内卦之位女正之，外卦之位男正之。故下三爻正内之事也，上三爻正外之事也。女人之道，其始也为人女，其中也为人妇，又其终也为人母。男子之道，其始也为人子，其中也为人夫，又其终也为人父。初爻「闲有家」，为人女之道也。二爻「在中馈」，为人妇之道也。三爻「家人嗃嗃」，为人母之道也。即彖辞所谓「正位乎内」也。四爻「富家吉」，为人子之道也。五爻「假有家」，为人夫之道也。上爻上爻「威如吉」，为人父之道也。即彖辞所谓「正位乎外」也。三曰「嗃嗃」，上曰「威如」。「威如嗃嗃」，严貌也，父母之道也。故曰：「家人有严君焉，父母之谓也。」是母道亦贵乎严也。男女之位正，则家道正；家道正，则天下定矣。</p><p>象曰：风自火出，家人，君子以言有物而行有恒。</p><p>风自火出，橐籥之火也。大凡鼓铸，须是鼓得许多。风从火里出，故风自火出，橐籥自有一个户庭阃奥，家之象也。就中必有模范。风也，火也，金也，器也，皆有模范。君子体之，言有物，行有恒。正家以身言，行，身之模范也；物，恒其则也。一身之模范，一家之模范；一家之模范，天下之模范也。</p><p>初九，闲有家，悔亡。象曰：「闲有家」，志未变也。</p><p>初言为人女之道。女子生则愿为之有家，当闲之于未从人之时，则可以无后悔也，故曰「闲有家，悔亡」。象曰「志未变也」。女子从人，则志变矣。六二，无攸遂，在中馈，贞吉。象曰：六二之吉，顺以巽也。二言为人妇之道。妇道不敢成事，故曰「无攸遂」；职在饮食之事，故曰「在中馈」；不与外言，故曰「贞吉」。所谓无非无仪，惟酒食是议者是也。象曰「顺以巽也」，顺以从夫也，所谓以顺为正者也。</p><p>九三，家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。象曰：「家人嗃嗃」，未失也；「妇子嘻嘻」，失家节也。</p><p>三言为人母之道也。嗃嗃，严肃貌。母道尚严，太严则不和，故有悔而厉。然与其狎而慢，宁若严而肃，故吉。若家政废弛，妇子嘻嘻然无所恐惧，则失母道矣，故「终吝」。象曰：「嗃嗃」，未失也。谓虽母过严，道未失也，若嘻嘻则失节矣。</p><p>六四，富家，大吉。象曰：「富家大吉」，顺在位也。</p><p>四言为人子之道，子而克家，则其家富矣，故曰「富家大吉」。象曰：顺在位也。居巽体，「巽」，顺也，言在子之位而能顺事父母也。九五，王假有家，勿恤，吉。象曰：「王假有家」，交相爱也。五言为人夫之道，居五应二，二尽妇道，五假而有之。五君位，故曰「王假有家」。得内助则无忧矣，故曰「勿恤吉」，象曰：「交相爱也。」</p><p>上九，有孚威如，终吉。象曰：「威如」之吉，反身之谓也。上言为人父之道，父子相遇必以诚，故曰「有孚」；义方之训必以严，故曰「威如」，此家道之终也。一卦六爻皆善，父子、夫妇、男女皆得其正也。一家皆正，则有终而吉矣！象曰「反身之谓也」。推原所以致吉，由修身而致也。盖修身则家齐，家齐则国治，国治则天下平矣。卦中六爻，不惟男女之位定，刚柔之位亦不可易。上，父道也。父道贵严，以九居之。五，夫道也。夫道贵义，以九居之。四，子道也。子道贵顺，以六居之。三，母道也。母道贵严，以九居之。二，妇道也。妇道贵顺，以六居之。初，女子之道，安得用刚？盖女子之未从人也，当以礼自防，不然，则为不有躬之女，故亦以九居之。六爻刚柔皆当，所以为家道之善。䷥ 兑下离上</p><p>睽，</p><p>睽：小事吉。彖曰：「睽」，火动而上，泽动而下。二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以「小事吉」。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也。睽之时，用火矣哉！</p><p>「睽」，离也。离与合对，天下之物不遽合也，必以离而合。圣人重卦，兑下离上，名卦以「聧」。泽性润下，火性炎上，固相违也，取义为「睽」。然水火未尝不相为用也，是以睽而合也。卦辞口「睽，小事吉」。当睽之时，未可遽合也。其合必以渐，故「小事吉」。彖曰：「火动而上，泽动而下」，水火之性「睽」也。二女同居，其志不同行。离与兑，二女也。女子始虽同居，终不同行，各从所适也。此圣人取「睽」之义也。然天下未有不以「睽」而合者，曰「小事吉」。盖就卦中以二象言之，虽「睽」，以六爻言之，下三爻居说体，上三爻居明体。离以丽也，以说而丽乎明，终必合也。六五以柔居上体得中而下应九二之刚，为刚柔正应，故可以有事也。以睽之功用言之，大而天地，则日月星辰之相为纪，风雨霜露之相为教，阴阳寒暑之相为亭毒，山岳川渎之相为融结，莫不以睽而相合者。至于人，则男女之相求，宾主之相交，君臣之相遇，朋友之相亲，莫不以「睽」而合者。微而至于物，则金木水火土之相为用，咸酸甘苦之相为味，玄黄赤白之相为文，金石丝竹之相为节，又莫不以「睽」而成功者。故曰：「天地睽而其志同，男女睽而其志通，万物睽而其事类。」则「睽」之一卦，思过半矣。六爻中纲领甚好。人伦有五，父子兄弟，其本同也，不以聧而合。夫妇、君臣、朋友，则以睽而合者也。故初以四言朋友之聧，二与五言君臣之睽，三与上言夫妇之睽。盖三者不睽，则不能合也。</p><p>象曰：上火下泽，「睽」。君子以同而异。</p><p>火炎上，泽润下，物之睽也。而水火未尝不相为用，是以睽而同也。同而异，异而同，异同之理，惟君子能知之。</p><p>初九，悔亡。丧马，勿逐，自复。见恶人，无咎。象曰：「见恶人」，以辟咎也。</p><p>初与四言朋友之睽，以刚应刚，朋友以义合也。同德相求，其交以诚，故曰「悔亡」。然有丧我而去者，不必逐之，听其自复可也。盖朋友之道，不可预为决择，恶人之来，不可绝也，见之则无咎。孔子于孺悲、阳货，亦为尽礼也。子夏所谓「我之不贤与，人将拒我，如之何其拒人也」？比之可者与之，不可者拒之，则狭矣。</p><p>九二，遇主于巷，无咎。象曰：「遇主于巷」，未失道也。</p><p>二五，君臣之位，故言君臣之「睽」。君臣之以「睽」而合者，非有所谓堂陛之素、半面之雅也，故曰「遇主于巷」。伊尹之莘野，太公之渭滨，诸葛孔明之草庐，皆自巷遇主也。故当事势睽离之时，君臣相求，必欲拘堂陛之常分，则贤者无自而进矣。「遇主于巷」，处「睽」之时则然，未矢道也。六三，见舆曳，其牛掣，其人天且劓，无初有终。象曰：「见舆曳」，位不当也；「无初有终」，遇刚也。</p><p>三与上应，言夫妇之睽矣。夫妇之道，其未合之时，皆判然也，未知上为己之应也。「舆曳」「牛掣」，见其车败也；其人髡首而劓鼻，见其人刑也。然车非真败，人非真败，人非真刑也，以礼自防，无因而至者，皆强暴也，故见其败且刑。然赖乎始之「睽」，故有终之合也，故曰「无初有终」，不如是，则不有其躬矣。九四，睽孤，遇元夫，交孚，厉无咎。象曰：「交孚」「无咎」，志行也。四与初应，所以「睽」者，上不下接也。四居上体，故「睽孤」在四。以九居初，元善之夫也。四能往遇，则「交孚」而相得矣，又须严厉自将，则「无咎」。盖交际之心不可不孚，而终始之义不可不敬，所谓「晏平仲善与人交，久而敬之」是也。象曰：「志行也。」「朋友以义合」，则其志同矣。</p><p>六五，悔亡。厥宗噬肤，往何咎？象曰：「厥宗噬肤」，往有庆也。五与二应，「睽」而相遇，情好款密，宜悔之亡也。二五正应，本同宗也，委巷相遇，誓言之信，不必歃牲之备也，「噬肤」可矣。古人有啮臂以相盟者，「噬肤」之谓也，然后不轻就也。义在则往，故曰「往何咎」。象曰：「往有庆也」，君臣以义合，其庆可知也。</p><p>上九，睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉。象曰：「遇雨」之「吉」，群疑亡也。</p><p>上九，六三之夫也。当「睽」之时，其见三也，「见豕负涂」，见其行也；「载鬼一车」，见其怪也。「先张之弧」，欲与之敌也；「后说之弧」，又欲与之亲也。上，「离」也；「三」，「坎」也。以「离」遇「坎」，则敌也。然上九也，六三也，以六应九，则又亲也，是「匪寇」也，乃「婚媾」也。「见豕」、「见鬼」、「张弧」、「说弧」，皆妖秽乖邪之事，阴阳氛沴所致。阴阳和则无是矣，故「往遇雨则吉」。「雨」，阴阳和也。象曰：「群疑亡也。」夫妇之情合，则向者败刑污怪之疑尽解矣。䷦ 艮下坎上</p><p>蹇</p><p>蹇：利西南，不利东北。利见大人，贞吉。彖曰：蹇，难也，险在前也。见险而能止，知矣哉！「蹇，利西南」，往得中也；「不利东北」，其道穷也。「利见大人」，往有功也。当位「贞吉」，以正邦也。蹇之时用大己哉！</p><p>「蹇」，滞也。何以滞？遇难而滞也。天下之为君子之学者，莫不欲得时行道，中天下而立，定四海之民，然后阴阳消长，与时偕行。君子之道，不能常通也，则遇险而正，姑退以自守，以大吾所养。天苟有平治天下之意，雷雨作而朋至，斯孚矣，此圣之所以处蹇也。卦，坎上艮下。「坎」，难也；「艮」，止也，见难而止也。曰「利西南，不利东北」，坎、艮，东北之卦也，合而成蹇，故不利东北。舍东北而西南，则蹇退矣。「利见大人」，九五也，得与五遇，则蹇道亨矣。人主，造命者也，天下之贫富贵贱，穷达亨否，皆由其轩轾，蹇所以「利见大人」也。然未可遽往也，故曰「贞吉」。彖：「蹇」，难也，险在前也，见险而能止，知矣哉！知时之不可为而止，惟如者能之。小人行险以求利，自以为知，人见其未尝不愚也。难不在西南，故往则得中；难在东北，失道而行，宜其穷也。大人，蹇之主，谓九五有「大蹇」之志，往遇之，则有功也。卦中六久，各当其其可，君子体之，是惟无用，用则正君国定矣，故曰「以正邦也」。惟不终蹇也，则「蹇」之时用大矣哉！</p><p>象曰：山上有水，「蹇」；君子以反身修德。</p><p>山上有水，止水也。夫水之流斯为川，塞斯为渊，塞而不流，「蹇」之象也。然水居山上，其畜益大，君子观之，反身修德以大其所养，则如万仞之渊决，而济物之功成矣！</p><p>初六，往蹇来誉。象曰：「往蹇来誉」，宜待也。</p><p>以柔在下，去五最远，往而遇险必蹇，不若退而自修，以成君子之名，故曰「往蹇来誉」。象曰「宜待也」，以待时之可也。</p><p>六二，王臣蹇蹇，匪躬之故。象曰：「王臣蹇蹇」，终无尤也。五爻皆「往蹇」而来，二独不言，而曰「王臣蹇蹇」，盖他爻非有官守者也。二与五为正应，居王臣之位，进退不能自必也。前遇互体为二「坎」，「蹇」而又「蹇」也。处重蹇之下，遇难而死难可也。所以然者，既已委质为臣，去就不由己也，故曰「匪躬之故」。象曰「终无尤也」，谓能「匪躬」则臣节无尤矣！</p><p>九三，往蹇来反。象曰：「往蹇来反」，内喜之也。</p><p>三临于险而居艮，得所止者也，往遇蹇则退而自反，故曰「往蹇来反」，象曰「内喜之也」，言反之得所乐也。</p><p>六四，往蹇来连。象曰：「往蹇来连」，当位实也。五非四应，往则必蹇，三善于止，不若退而连，故曰「往蹇来连」，象曰「当位实也」。三有实德，已与之连而得当也。</p><p>九五，大蹇朋来。象曰：「大蹇朋来」，以中节也。</p><p>以九五之君，正位在乾卦，则贤者云龙风虎之会也。而处蹇之世，使在下者皆怀有不自满之意而去，其为九五之累多矣。五有刚健中正之德，大亨天下之蹇，使之各以朋类而来，则贤者无濡滞之叹，故曰「大蹇朋来」，象曰「以中节也」。贤者无濡滞之叹，则得喜怒哀乐之正，故曰「中节」。</p><p>上六，往蹇来硕，吉，利见大人。象曰：「往蹇来硕」，志在内也。「利见大人」，以从贵也。</p><p>硕，大也。六往过蹇，退而得五，五已有大蹇之志矣，故曰「往蹇来硕吉。利见大人」。象曰：志在内也。上位在外，来与五遇，故曰「志在内也」。阳贵阴贱，利见九五，故曰「以从贵也」。䷧ 坎下震上</p><p>解</p><p>解：利西南，无所往，其来复，吉。有攸往，夙吉。彖曰：「解」，险以动，动而免乎险，解。「解利西南」，往得众也；「其来复吉」，乃得中也；「有攸往，夙吉」，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲拆，解之时大矣哉！</p><p>「蹇」变而「解」，坎险居下，震动居上，动而出乎险难，解之象也。曰「利西南，无所往，其来复，吉。有攸往，夙吉」。此卦乃蹇卦之反。处蹇之时，则「利西南，无所往」而来复，则得「吉」，如「往蹇来反」之类。今「蹇」散为「解」，则向之「利西南」，无所可往而来反则得「吉」者，今可以有所往，而豫知其得吉也，故曰「有攸往，夙吉」。先儒不知卦自蹇来，反遂牵于「无所往吉」，又「有攸往吉」，故其说不定。彖曰：「解」，险以动，动而免乎险，解。「震」在坎上，动处险之外，是「动而免乎险」也。难在东北，则利在西南，宜其得众也。「其来复吉」，乃得中也。未可往，则以来往为中也。今难既险，则往而有功矣，是以「有所往」为功也。盖天地之理不终难也，难极则必「解」。天地未解之时，则云雷为屯；天地既解，则雷雨作，万物皆有发生之意矣。当君子未解难之时，天下之人在虐政膏火中，人未知有生生之所。君子既解难，则人命始有所迓续矣。故「解」之时大矣哉！</p><p>象曰：雷雨作，「解」，君子以赦过宥罪。</p><p>云雷未成雨为屯，雷雨既作为「解」。阴阳之气郁结而解散则成雨，难解之象也。当难解而赦过宥罪，与之日新，则小人无所疑也。</p><p>初六：无咎。象曰：「刚柔之际，义无咎也。」</p><p>六爻二阳而四阴，当君子解小人之象，时小人尚据尊位。盖解卦为患难方解之始，小人犹未去，君子正当用力。九二、九四当解之责，六三、六五、上六为在位小人，初六一阴居二阳之下，是自知退听者也。小人自知退而咎之可也，盖君子不为已甚。象曰：「刚柔之际，义无咎也。」初六一柔，本在上体，反而居下，与二阳相遇，宜其「无咎」也。</p><p>九二，田获三狐，得黄矢，贞吉。象曰：九二「贞吉」，得中道也。二为解难之君子，「田获三狐，得黄矢」，盖三则为群，谓上二阴也，必尽小人之群而得之，而利器未尝失，获狐得矢，不遗一镞也。以此解难，得正而吉也。象曰：「得中道也。」以二得中，故为解难之善。</p><p>六三，负且乘，致寇至，贞吝。象曰：「负且乘」，亦可丑也。自我致戎，又谁咎也。当解难之时，六阴也，犹据下卦之上，小人而乘车也，据非其所，其祸必至，故曰「负且乘，致寇至」。象曰：「负且乘」，亦可丑也。非其所据，众所耻也。「自我致戎，又谁咎也」，祸自己致，又将谁咎？系辞：「子曰：作易者，其知盗乎？易曰：负且乘，致寇至。」负也者，小人之事；乘也者，君子之器也。小人而乘君子之器，盗思夺之矣；上慢下暴，盗思伐之矣。慢藏诲盗，冶容诲淫。易曰：负且乘，致寇至，盗之招也。九四，解而拇，朋至斯孚。象曰：「解而拇」，未当位也。</p><p>拇最下，以九居四为解难之君子，而下应初六，犹有保祐小人之意，必解去之，则君子之朋至而相孚矣。象曰：「未当位也。」四不得中，故有此戒。</p><p>六五，君子维有解，吉。有孚于小人。象曰：「君子有解」，小人退也。</p><p>六五为「解」之主，己居君位。当「解」之时，小人犹得君而未去，然君子之解不可已也，六五何以处之？孚于小人，使之自为去就，以避贤者路可也。象曰：「君子有解，小人退也。」言君子必解难，则小人自当退也。</p><p>上六，公用射隼于高墉之上，获之，无不利。象曰：「公用射隼」，以解悖也。</p><p>既「解」至五，而阴犹据六，是在「高墉」之象也。「公」，谓九四也，必射而获之，然后尽解道之善，而「解」道成矣。盖此一阴独据高位，窃威福之权，而在己者「解」而不获，必反为害，所谓断蛇不殊者也。象曰：「以解悖也。」获此一阴，则乱去矣。系辞：「子曰：隼者，禽也；弓矢者，器也；射之者，人也。君子藏器于身，待时而动，何不利之有？」动而不括，是以出而有获，语成器而动者也。必成器而后动，谨之至也。西溪易说卷八，</p>',68)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
